import java.util.concurrent.ConcurrentHashMap;
import java.util.Map;

public class ConcurrentMapDemo {
    public static void main(String[] args) {
        ConcurrentHashMap<String, Integer> map = new ConcurrentHashMap<>();

        // putIfAbsent — solo agrega si no existe
        map.put("a", 1);
        Integer old = map.putIfAbsent("a", 99);
        System.out.println("Valor anterior: " + old); // 1
        System.out.println("Valor actual: " + map.get("a")); // 1

        // compute — calcula nuevo valor
        map.compute("a", (key, val) -> val == null ? 0 : val + 10);
        System.out.println("Despues de compute: " + map.get("a")); // 11

        // merge — merge con valor existente
        map.merge("b", 5, Integer::sum); // agrega 5
        map.merge("b", 3, Integer::sum); // suma 3
        System.out.println("Valor de b: " + map.get("b")); // 8

        // computeIfAbsent — solo calcula si no existe
        map.computeIfAbsent("c", k -> k.hashCode() % 100);
        System.out.println("Valor de c: " + map.get("c"));

        // No permite null
        try {
            map.put(null, 1);
        } catch (NullPointerException e) {
            System.out.println("Null key no permitido");
        }
    }
}

