public class MutableKeyHell {
    public static void main(String[] args) {
        Set<MutableKey> set = new HashSet<>();
        MutableKey key = new MutableKey("original");

        set.add(key);
        System.out.println("Contiene original: " + set.contains(key)); // true
        System.out.println("Tamano: " + set.size()); // 1

        // Modificar el key — hashCode cambia!
        key.setName("modified");
        System.out.println("\nDespues de modificar:");
        System.out.println("Contiene modified: " + set.contains(key)); // false!
        System.out.println("Tamano: " + set.size()); // 1 — pero no puedes encontrarlo!

        // Solucion: crear un nuevo objeto con el nuevo valor
        MutableKey newKey = new MutableKey("modified");
        set.add(newKey);
        System.out.println("\nCon nuevo objeto:");
        System.out.println("Contiene newKey: " + set.contains(newKey)); // true
        System.out.println("Tamano: " + set.size()); // 2 — ahora hay dos!
        System.out.println("Set: " + set);
    }
}

class MutableKey {
