    @Override public boolean equals(Object o) {
        if (this == o) return true;
        if (o == null || getClass() != o.getClass()) return false;
        return Objects.equals(name, ((MutableKey) o).name);
    }
    @Override public int hashCode() { return Objects.hash(name); }
    public String toString() { return name; }
}

import java.util.*;

public class ComparableComparatorDemo {
    public static void main(String[] args) {
        // Comparable — orden natural (String implementa Comparable)
        List<String> names = new ArrayList<>(Arrays.asList("Charlie", "Alice", "Bob"));
        Collections.sort(names); // usa compareTo()
        System.out.println("Comparable: " + names); // [Alice, Bob, Charlie]

        // Comparator — orden inverso
        names.sort(Comparator.reverseOrder());
        System.out.println("Reverso: " + names); // [Charlie, Bob, Alice]

        // Comparator con comparing
        List<String> cities = Arrays.asList("Bogota", "Medellin", "Cali");
        cities.sort(Comparator.comparingInt(String::length));
        System.out.println("Por longitud: " + cities); // [Cali, Bogota, Medellin]

        // Comparator encadenado
        List<String> data = Arrays.asList("Charlie", "Bob", "Alice", "David");
        data.sort(Comparator
            .comparingInt(String::length)  // primero por longitud
            .thenComparing(Comparator.naturalOrder())  // luego alfabeticamente
        );
        System.out.println("Encadenado: " + data); // [Bob, David, Alice, Charlie]

        // nullsFirst / nullsLast
        List<String> withNull = Arrays.asList("B", null, "A", null, "C");
        withNull.sort(Comparator.nullsFirst(Comparator.naturalOrder()));
        System.out.println("nullsFirst: " + withNull); // [null, null, A, B, C]
    }
}

