        // Copia — independiente
        List<String> copy = List.copyOf(mutable);
        mutable.add("E");
        System.out.println("\nDespues de agregar E:");
        System.out.println("Original: " + mutable); // [A, B, C, D, E]
        System.out.println("Copia: " + copy); // [A, B, C, D] — no cambia!

        // Con Map
        Map<String, Integer> mapMutable = new HashMap<>(Map.of("x", 1));
        Map<String, Integer> mapWrapper = Collections.unmodifiableMap(mapMutable);
        mapMutable.put("y", 2);
        System.out.println("\nMap wrapper: " + mapWrapper); // {x=1, y=2}
    }
