import java.util.*;

public class ComplexityBenchmark {
    public static void main(String[] args) {
        int n = 1_000_000;

        // ArrayList sin capacidad pre-definida
        List<Integer> a = new ArrayList<>();
        long t0 = System.nanoTime();
        for (int i = 0; i < n; i++) a.add(i);
        long t1 = System.nanoTime();
        System.out.printf("ArrayList sin capacity: %.2f ms%n", (t1-t0)/1e6);

        // ArrayList con capacidad pre-definida
        List<Integer> b = new ArrayList<>(n);
        long t2 = System.nanoTime();
        for (int i = 0; i < n; i++) b.add(i);
        long t3 = System.nanoTime();
        System.out.printf("ArrayList con capacity: %.2f ms%n", (t3-t2)/1e6);

        // HashMap sin capacidad
        Map<Integer, Integer> c = new HashMap<>();
        long t4 = System.nanoTime();
        for (int i = 0; i < n; i++) c.put(i, i);
        long t5 = System.nanoTime();
        System.out.printf("HashMap sin capacity: %.2f ms%n", (t5-t4)/1e6);

        // HashMap con capacidad
        Map<Integer, Integer> d = new HashMap<>(n * 2);
        long t6 = System.nanoTime();
        for (int i = 0; i < n; i++) d.put(i, i);
        long t7 = System.nanoTime();
        System.out.printf("HashMap con capacity: %.2f ms%n", (t7-t6)/1e6);
    }
}

import java.util.*;
import java.util.stream.*;

public class FunctionalOperations {
    public static void main(String[] args) {
        // removeIf — elimina pares donde value > 2
        Map<String, Integer> scores = new LinkedHashMap<>(Map.of(
            "Alice", 3, "Bob", 1, "Charlie", 4, "David", 2
        ));
        System.out.println("Original: " + scores);

        scores.entrySet().removeIf(e -> e.getValue() > 2);
        System.out.println("Sin values > 2: " + scores); // {Bob=1, David=2}

        // compute — incrementar valor
        Map<String, Integer> counters = new HashMap<>();
        counters.merge("a", 1, Integer::sum);
        counters.merge("a", 1, Integer::sum);
        counters.merge("b", 1, Integer::sum);
        System.out.println("Contadores: " + counters); // {a=2, b=1}

        // computeIfAbsent — inicializar
        Map<String, List<String>> groups = new HashMap<>();
        String[] words = {"apple", "banana", "avocado", "blueberry"};
        for (String w : words) {
            String key = w.substring(0, 1);
            groups.computeIfAbsent(key, k -> new ArrayList<>()).add(w);
        }
        System.out.println("Grupos: " + groups); // {a=[apple, avocado], b=[banana, blueberry]}

        // Streams — collect
        Map<String, Integer> data = Map.of("a", 1, "b", 2, "c", 3, "d", 4);
        Map<Boolean, List<Integer>> partitioned = data.values().stream()
            .collect(Collectors.partitioningBy(v -> v % 2 == 0));
        System.out.println("Pares/Impares: " + partitioned);
    }
}

