import java.util.concurrent.ConcurrentHashMap;
import java.util.*;
import java.util.stream.*;

public class ConcurrentMapAdvanced {
    public static void main(String[] args) {
        ConcurrentHashMap<String, Integer> map = new ConcurrentHashMap<>();

        // Contador atomico
        String[] words = {"java", "python", "java", "rust", "python", "java"};
        for (String w : words) {
            map.merge(w, 1, Integer::sum);
        }
        System.out.println("Conteo: " + map); // {java=3, python=2, rust=1}

        // Grouping atomico
        ConcurrentHashMap<String, List<String>> groups = new ConcurrentHashMap<>();
        String[] data = {"apple", "banana", "avocado", "blueberry", "cherry"};
        for (String d : data) {
            groups.computeIfAbsent(d.substring(0, 1), k -> new ArrayList<>()).add(d);
        }
        System.out.println("Grupos: " + groups);

        // Cache atomico
        ConcurrentHashMap<String, String> cache = new ConcurrentHashMap<>();
        cache.computeIfAbsent("key1", k -> {
            System.out.println("Cargando " + k + "...");
            return "value1";
        });
        cache.computeIfAbsent("key1", k -> {
            System.out.println("Esto no se imprime (ya existe)");
            return "value2";
        });
        System.out.println("Cache: " + cache);

        // Search y reduce
        Optional<String> found = map.search(1, (k, v) -> v > 2 ? k : null);
        System.out.println("Encontrado (value > 2): " + found.orElse("none"));

        int total = map.reduce(1, (k, v) -> v, Integer::sum);
        System.out.println("Total: " + total);
    }
}

